# Generated by secure-by-design v0.1.0 for AI accountability (ISO 27001 A.8.15 +
# alignment with ISO/IEC 42001 §8.4 and EU AI Act Art. 12-style logging).
# Reads from ../../privacy-security-manifest.yaml.
# Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
# Docs: docs/scaffolds/decision_log.md
#
# Every AI inference flows through this wrapper. It records:
#   - which AI system (matches aiSystems[].name in manifest)
#   - the input categories (without raw PHI/PII — only category names)
#   - a hash of the output (and a redacted preview, only if you set a redactor)
#   - latency, model id, prompt+response token counts
#   - whether human oversight gate was invoked (and outcome)
#
# You can replay this log to: audit, debug, monitor for drift, support
# data-principal access (DPDP §11) for AI-mediated decisions.

from __future__ import annotations

import asyncio
import dataclasses
import hashlib
import json
import sys
import time
from collections.abc import Awaitable, Callable, Mapping
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any, Literal, Protocol, TypeVar

from ..security.audit_log import audit_log, redact

T = TypeVar('T')


@dataclass(frozen=True, kw_only=True)
class DecisionContext:
    system_name: str                   # matches manifest.aiSystems[].name
    actor: str                         # who triggered (physician ID, service ID)
    input_category_names: list[str]    # categories from manifest (not raw data!)
    data_principal_id: str | None = None  # patient / data principal whose data is processed
    model_id: str | None = None        # populated by the wrapped call when available
    metadata: Mapping[str, Any] | None = None


@dataclass(frozen=True, kw_only=True)
class DecisionRecord(DecisionContext):
    timestamp: str
    latency_ms: int
    outcome: Literal['success', 'failure', 'oversight-blocked']
    output_hash: str | None = None     # SHA-256 of stringified output
    output_preview: str | None = None  # first 200 chars, PHI-redacted
    error: str | None = None
    tokens_in: int | None = None
    tokens_out: int | None = None
    oversight_required: bool | None = None
    oversight_provided_by: str | None = None


class DecisionSink(Protocol):
    async def write(self, record: DecisionRecord) -> None: ...


class StderrDecisionSink:
    async def write(self, record: DecisionRecord) -> None:
        fields = {k: v for k, v in dataclasses.asdict(record).items() if v is not None}
        sys.stderr.write(json.dumps({'kind': 'ai-decision', **fields}, default=str) + '\n')


_sink: DecisionSink = StderrDecisionSink()


def set_decision_sink(sink: DecisionSink) -> None:
    global _sink
    _sink = sink


def _stringify(value: Any) -> str:
    return value if isinstance(value, str) else json.dumps(value, default=str)


def _hash_of(value: Any) -> str:
    return hashlib.sha256(_stringify(value).encode('utf-8')).hexdigest()


# Off by default: pattern-based redaction misses names and clinical free text, so a preview
# of model output can leak personal data into the log. Opt in with a redactor you trust,
# for example set_preview_redactor(phi_redact) from ..security.phi_redaction.
_preview_redactor: Callable[[str], str] | None = None


def set_preview_redactor(redactor: Callable[[str], str]) -> None:
    global _preview_redactor
    _preview_redactor = redactor


def _preview_of(value: Any) -> str | None:
    if _preview_redactor is None:
        return None
    # Redact before cutting: a value split at the cut no longer matches a pattern.
    return _preview_redactor(_stringify(value))[:200]


def _elapsed_ms(started_at: float) -> int:
    return round((time.monotonic() - started_at) * 1000)


async def decision_log(ctx: DecisionContext, fn: Callable[[], Awaitable[T]]) -> T:
    """
    Wrap an AI inference call. Every AI invocation in your product should be wrapped.

      result = await decision_log(
          DecisionContext(system_name='clinical-suggestion-engine', actor=physician_id,
                          data_principal_id=patient_id, input_category_names=['patient-clinical']),
          lambda: client.chat.completions.create(model='gpt-4o', messages=[...]),
      )

    Pass an async call; wrap a blocking SDK in asyncio.to_thread. The result is returned
    as-is; the side effect is the decision log record.
    """
    timestamp = datetime.now(timezone.utc).isoformat()
    started_at = time.monotonic()
    fields = {f.name: getattr(ctx, f.name) for f in dataclasses.fields(ctx)}

    try:
        result = await fn()
    except (Exception, asyncio.CancelledError) as e:
        # Model errors can echo the prompt, so the message is redacted here too.
        error = redact(str(e)) or type(e).__name__
        failure = DecisionRecord(
            **fields,
            timestamp=timestamp,
            latency_ms=_elapsed_ms(started_at),
            outcome='failure',
            error=error,
        )
        await _sink.write(failure)
        await audit_log.event(
            f'ai.{ctx.system_name}.inference',
            actor=ctx.actor,
            target=ctx.data_principal_id,
            severity='ERROR',
            outcome='failure',
            attrs={'latency_ms': failure.latency_ms, 'error': error},
        )
        raise

    record = DecisionRecord(
        **fields,
        timestamp=timestamp,
        latency_ms=_elapsed_ms(started_at),
        outcome='success',
        output_hash=_hash_of(result),
        output_preview=_preview_of(result),
    )
    await _sink.write(record)
    await audit_log.event(
        f'ai.{ctx.system_name}.inference',
        actor=ctx.actor,
        target=ctx.data_principal_id,
        attrs={'latency_ms': record.latency_ms, 'output_hash': record.output_hash},
    )
    return result
